<?php
declare(strict_types=1);
namespace app\common\service\app\aigc_copywriting;
use think\facade\Db;
final class CopywritingToolService {
 public static function lists(int $tenantId,bool $public=false,string $terminal='h5'):array {$rows=CopywritingStore::table('tool')->alias('t')->leftJoin('aigc_copywriting_page p','p.tool_id=t.id AND p.tenant_id=t.tenant_id')->where(['t.tenant_id'=>$tenantId,'t.delete_time'=>0]);if($public)$rows->where('t.status',1)->where('p.published_version_id','>',0);$data=$rows->field('t.*,p.id as page_id,p.published_version_id as version_id')->order(['t.sort'=>'desc','t.id'=>'asc'])->select()->toArray();$data=array_map(function($row){$row['icon']=empty($row['icon'])?'':\app\common\service\FileService::getFileUrl((string)$row['icon']);return $row;},$data);return array_values(array_filter($data,function($row)use($public,$terminal,$tenantId){if(!$public)return true;$v=CopywritingStore::owned('version',$tenantId,(int)$row['version_id']);return in_array($terminal,explode(',',$v['publish_targets']),true);}));}
 public static function detail(int $tenantId,string $code,string $terminal='h5'):array {$tool=CopywritingStore::table('tool')->where(['tenant_id'=>$tenantId,'tool_code'=>$code,'status'=>1,'delete_time'=>0])->find();if(!$tool)throw new \InvalidArgumentException('功能不存在或已下架');$page=CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'tool_id'=>$tool['id']])->find();if(!$page||!$page['published_version_id'])throw new \InvalidArgumentException('该功能尚未发布');$v=CopywritingStore::owned('version',$tenantId,(int)$page['published_version_id']);if(!in_array($terminal,explode(',',$v['publish_targets']),true))throw new \InvalidArgumentException('该功能尚未发布到当前终端');return $tool+['version_id'=>$v['id'],'document'=>CopywritingDocument::publicDocument(CopywritingStore::decode($v['document_json']))];}
 public static function create(int $tenantId,int $actorId,array $input):array {return Db::transaction(function()use($tenantId,$actorId,$input){CopywritingStore::owned('category',$tenantId,(int)$input['category_id']);$name=trim((string)($input['name']??''));if(!$name||mb_strlen($name)>80)throw new \InvalidArgumentException('请填写80字以内功能名称');$code='tool_'.bin2hex(random_bytes(8));$id=CopywritingStore::insert('tool',['tenant_id'=>$tenantId,'tool_code'=>$code,'name'=>$name,'category_id'=>(int)$input['category_id'],'description'=>mb_substr((string)($input['description']??''),0,255),'icon'=>self::icon($input['icon']??''),'is_customized'=>1]);$d=$input['document']??CopywritingSeeder::catalog()[0]['document'];$page=CopywritingStore::insert('page',['tenant_id'=>$tenantId,'page_code'=>$code,'kind'=>'tool','tool_id'=>$id,'draft_json'=>CopywritingStore::json(CopywritingDocument::normalize($d))]);CopywritingStore::audit($tenantId,$actorId,'create','tool',$id);return ['id'=>$id,'page_id'=>$page,'tool_code'=>$code];});}
 public static function save(int $tenantId,int $actorId,array $input):array {$id=(int)$input['id'];$existing=CopywritingStore::owned('tool',$tenantId,$id);CopywritingStore::owned('category',$tenantId,(int)$input['category_id']);$name=trim((string)$input['name']);if(!$name||mb_strlen($name)>80)throw new \InvalidArgumentException('功能名称不合法');CopywritingStore::table('tool')->where(['tenant_id'=>$tenantId,'id'=>$id])->update(['name'=>$name,'icon'=>self::icon($input['icon']??$existing['icon']),'description'=>mb_substr((string)($input['description']??''),0,255),'category_id'=>(int)$input['category_id'],'status'=>!empty($input['status'])?1:0,'sort'=>(int)($input['sort']??0),'is_customized'=>1,'update_time'=>time()]);return CopywritingStore::owned('tool',$tenantId,$id);}
 public static function delete(int $tenantId,int $actorId,int $id):void {CopywritingStore::owned('tool',$tenantId,$id);CopywritingStore::table('tool')->where(['tenant_id'=>$tenantId,'id'=>$id])->update(['delete_time'=>time(),'status'=>0]);CopywritingStore::audit($tenantId,$actorId,'delete','tool',$id);}
 public static function copy(int $tenantId,int $actorId,int $id):array {$tool=CopywritingStore::owned('tool',$tenantId,$id);$p=CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'tool_id'=>$id])->find();return self::create($tenantId,$actorId,['name'=>$tool['name'].' 副本','category_id'=>$tool['category_id'],'icon'=>$tool['icon'],'description'=>$tool['description'],'document'=>CopywritingStore::decode($p['draft_json'])]);}
 public static function restore(int $tenantId,int $actorId,int $id):array {$tool=CopywritingStore::owned('tool',$tenantId,$id);$source=null;foreach(CopywritingSeeder::catalog()as $s)if($s['code']===$tool['builtin_code'])$source=$s;if(!$source)throw new \InvalidArgumentException('自建功能没有内置默认模板');$p=CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'tool_id'=>$id])->find();return CopywritingPageService::saveDraft($tenantId,$actorId,(int)$p['id'],(int)$p['draft_revision'],$source['document']);}
 private static function icon($value): string {$icon=trim((string)$value);if(strlen($icon)>255||preg_match('/[\x00-\x20<>]/',$icon)||($icon!==''&&!preg_match('~^(?:https?://[^/]+/|/?(?:uploads|resource)/)~i',$icon)))throw new \InvalidArgumentException('图标请选择图片或填写有效图片地址（255字符以内）');return $icon;}
}
